svg.script:
(function(){
var svg=document.documentElement,NS='http://www.w3.org/2000/svg';
var vb=svg.viewBox.baseVal;
var VW=(vb&&vb.width)||svg.clientWidth||1085, VH=(vb&&vb.height)||svg.clientHeight||708, MIN=Math.min(VW,VH);
var tiles=[].slice.call(document.querySelectorAll('path')), N=tiles.length;
for(var q=0;q<N;q++)tiles[q]._ti=q;

/* ---- structural class: per-path matrix (B) vs group transform (A) ---- */
var CLASSB=/matrix/.test(tiles[0]&&tiles[0].getAttribute('transform')||'');
var grp=svg.querySelector('g'), Ginv={a:1,b:0,c:0,d:1};
function updGinv(){if(!grp||!grp.transform.baseVal.numberOfItems){return;}var m=grp.transform.baseVal.consolidate();if(m){var x=m.matrix,det=x.a*x.d-x.b*x.c||1;Ginv={a:x.d/det,b:-x.b/det,c:-x.c/det,d:x.a/det};}}
if(!CLASSB){var st=document.createElementNS(NS,'style');st.textContent='path{transform-box:fill-box;transform-origin:center}';svg.appendChild(st);}

/* ---- color detection + palettes ---- */
function norm(h){h=(h||'').toLowerCase().trim();if(h.length===4&&h[0]==='#')h='#'+h[1]+h[1]+h[2]+h[2]+h[3]+h[3];return h;}
function h2r(h){h=norm(h).replace('#','');return [parseInt(h.slice(0,2),16),parseInt(h.slice(2,4),16),parseInt(h.slice(4,6),16)];}
function r2h(a){return '#'+a.map(function(v){return ('0'+Math.max(0,Math.min(255,Math.round(v))).toString(16)).slice(-2);}).join('');}
function hueOf(r){var R=r[0]/255,G=r[1]/255,B=r[2]/255,mx=Math.max(R,G,B),mn=Math.min(R,G,B),d=mx-mn,h=0;if(d){if(mx===R)h=((G-B)/d)%6;else if(mx===G)h=(B-R)/d+2;else h=(R-G)/d+4;}h*=60;if(h<0)h+=360;return h;}
function keyOf(r){var sat=Math.max(r[0],r[1],r[2])-Math.min(r[0],r[1],r[2]);return sat<12?(r[0]+r[1]+r[2])/3:1000+hueOf(r);}
var fills=tiles.map(function(p){return norm(p.getAttribute('fill'));}),seen={},distinct=[];
fills.forEach(function(f){if(f&&f!=='none'&&!(f in seen)){seen[f]=1;distinct.push(f);}});
distinct.sort(function(a,b){return keyOf(h2r(a))-keyOf(h2r(b));});
var slotMap={};distinct.forEach(function(f,i){slotMap[f]=i;});
var origRGB=distinct.map(h2r),slotOf=fills.map(function(f){return (f in slotMap)?slotMap[f]:0;});
var NAMED=[['AURORA',['#77e3bb','#2bd6a0','#d42222','#e651e9','#e836a3','#ffd166']],['SUNSET',['#ffd166','#ff9e4a','#ff6b6b','#ef476f','#c9457f','#8a2be2']],['OCEAN',['#caf0f8','#90e0ef','#00b4d8','#0077b6','#023e8a','#03045e']],['LAGOON',['#d8f3dc','#74c69d','#40916c','#1b9aaa','#118ab2','#073b4c']],['NEON',['#39ff14','#00f5d4','#05d9e8','#ff206e','#fee440','#fb5607']],['EMBER',['#fff3b0','#ffba08','#ff8800','#e85d04','#dc2f02','#9d0208']],['VAPOR',['#ff71ce','#b967ff','#01cdfe','#05ffa1','#fffb96','#ff9cee']],['FOREST',['#dde5b6','#a4c639','#588157','#3a5a40','#344e41','#a68a64']],['CANDY',['#ffadad','#ffd6a5','#fdffb6','#caffbf','#9bf6ff','#bdb2ff']],['ROYAL',['#f72585','#b5179e','#7209b7','#560bad','#3a0ca3','#4361ee']],['MONO',['#f5efe3','#cbbfa6','#9a8c73','#6b5d49','#3d342a','#1c1814']],['FIREICE',['#03045e','#0096c7','#caf0f8','#ffba08','#dc2f02','#6a040f']],['TWILIGHT',['#0d1b2a','#1b263b','#415a77','#778da9','#c0a9d6','#e0b1cb']],['CORAL',['#ee6c4d','#ff9b85','#ffd97d','#fff0b5','#aaf0d1','#5bc0be']],['AUTUMN',['#582f0e','#7f4f24','#936639','#a68a64','#b6ad90','#c2c5aa']],['ICE',['#e8f7ff','#caf0f8','#ade8f4','#90e0ef','#48cae4','#00b4d8']],['MAGMA',['#000004','#3b0f70','#8c2981','#de4968','#fe9f6d','#fcfdbf']],['VIRIDIS',['#440154','#414487','#2a788e','#22a884','#7ad151','#fde725']],['PLASMA',['#0d0887','#6a00a8','#b12a90','#e16462','#fca636','#f0f921']],['RAINBOW',['#e63946','#f3722c','#f9c74f','#90be6d','#43aa8b','#577590']],['SAKURA',['#ffe5ec','#ffc2d1','#ff8fab','#fb6f92','#c9184a','#590d22']],['DESERT',['#edc9af','#e0a458','#c97b4a','#a44a3f','#dab785','#8a5a44']],['GALAXY',['#03071e','#240046','#3c096c','#7b2cbf','#c77dff','#e0aaff']],['CITRUS',['#d8f3a3','#b5e48c','#dde26a','#f9dc5c','#fcae1e','#f77f00']]];
var PAL=[{n:'ORIGINAL',c:origRGB.slice()}].concat(NAMED.map(function(p){return {n:p[0],c:p[1].map(h2r)};}));
function slotCol(p,s){return p.c[s%p.c.length];}
var palIdx=0,curRGB=origRGB.map(function(c){return c.slice();}),tgtRGB=origRGB.map(function(c){return c.slice();}),recolor=false;

/* ---- per-tile base matrix + center (viewBox space, universal) ---- */
function parseM(p){var t=p.getAttribute('transform')||'',m=t.match(/matrix\(([^)]+)\)/);if(!m)return [1,0,0,1,0,0];var n=m[1].split(/[ ,]+/).map(Number);return n.length>=6?n.slice(0,6):[1,0,0,1,0,0];}
var BM=CLASSB?tiles.map(parseM):null, baseStr=CLASSB?BM.map(function(M){return 'matrix('+M[0]+' '+M[1]+' '+M[2]+' '+M[3]+' '+M[4]+' '+M[5]+')';}):null;
var cx=new Float64Array(N),cy=new Float64Array(N);
var ox=new Float64Array(N),oy=new Float64Array(N),vx=new Float64Array(N),vy=new Float64Array(N);
var sc=new Float64Array(N),br=new Float64Array(N),picked=new Uint8Array(N),dirty=new Uint8Array(N);
for(var z=0;z<N;z++)sc[z]=1;
var ctmInv=null;function updCTM(){var m=svg.getScreenCTM();if(m)ctmInv=m.inverse();}
function measure(){updCTM();updGinv();var p=svg.createSVGPoint();for(var i=0;i<N;i++){var r=tiles[i].getBoundingClientRect();p.x=r.left+r.width/2;p.y=r.top+r.height/2;var v=p.matrixTransform(ctmInv);cx[i]=v.x;cy[i]=v.y;}}
measure();

/* ---- ocean wave field (Gerstner) ---- */
var WV=[{a:[0.95,0.20],L:VW*0.46,amp:0.55,sp:0.55,q:0.85},{a:[0.45,0.92],L:VW*0.28,amp:0.40,sp:0.78,q:0.80},{a:[-0.7,0.55],L:VW*0.17,amp:0.24,sp:1.10,q:0.70},{a:[0.20,-0.98],L:VW*0.11,amp:0.14,sp:1.55,q:0.60}];
var W=WV.length,kW=[],dW=[],ampR=[],spW=[],qW=[],sumA=0;
WV.forEach(function(w){var n=Math.hypot(w.a[0],w.a[1])||1;dW.push([w.a[0]/n,w.a[1]/n]);kW.push(2*Math.PI/w.L);ampR.push(w.amp);spW.push(w.sp);qW.push(w.q);sumA+=w.amp;});
var spPh=new Float64Array(N*W);for(var i3=0;i3<N;i3++)for(var w3=0;w3<W;w3++)spPh[i3*W+w3]=kW[w3]*(dW[w3][0]*cx[i3]+dW[w3][1]*cy[i3]);

/* ---- config ---- */
var CFG={R:MIN*0.30,SPRING:0.018,FR:0.86,MAXO:MIN*0.20,PUSH:0.85,SWIRL:0.75,GROW:0.7,BRIGHT:0.6,WAVE_AMP:MIN*0.030,WAVE_EASE:0.16,CREST_S:0.55,CREST_B:0.7,SWELL_AMP:MIN*0.05,RIP_SPEED:MIN*0.013,RIP_W:MIN*0.05,RIP_AMP:MIN*0.022,RIP_PUSH:1.4,RIP_SCALE:0.9,LENS_MAG:0.95,PICK_MAG:0.8,IDLE_MS:3500};
var MODES=['OCEAN','SWELL','REPEL','ATTRACT','VORTEX','LENS','PICK'];
var mode=0,gains=[1,1,1,1,1,1,1],speed=1,radiusScale=1,haloOn=true;
var STRIDE=N>4200?3:(N>2200?2:1),DOFILTER=N<=1700;

/* ---- halo + HUD ---- */
var defs=document.createElementNS(NS,'defs');
defs.innerHTML='<radialGradient id="halo"><stop offset="0%" stop-color="#fff" stop-opacity="0.8"/><stop offset="45%" stop-color="#fff" stop-opacity="0.18"/><stop offset="100%" stop-color="#fff" stop-opacity="0"/></radialGradient>';
svg.appendChild(defs);
var glow=document.createElementNS(NS,'circle');glow.setAttribute('fill','url(#halo)');glow.setAttribute('cx',-9999);glow.setAttribute('cy',-9999);glow.style.mixBlendMode='screen';glow.style.pointerEvents='none';glow.style.transition='opacity .4s';glow.style.opacity='0';svg.appendChild(glow);
function setHaloR(){glow.setAttribute('r',MIN*0.27*radiusScale);}setHaloR();
function haloShow(){return haloOn&&mode<5;}
function setGlow(x,y,on){glow.setAttribute('cx',x);glow.setAttribute('cy',y);glow.style.opacity=(on&&haloShow())?'0.42':'0';}
var hud=document.createElementNS(NS,'g');hud.setAttribute('id','hud');
hud.innerHTML='<rect x="16" y="16" width="640" height="178" rx="12" fill="#ede4d3" fill-opacity="0.62" stroke="#0000001f"/>'+
 '<text x="34" y="50" font-size="22" font-weight="700" letter-spacing="3">~ TESSELLATION ~</text>'+
 '<text id="hHint" x="34" y="78" font-size="14" fill-opacity="0.82"></text>'+
 '<text id="hMode" x="34" y="104" font-size="15"></text>'+
 '<text id="hMeta" x="34" y="128" font-size="14"></text>'+
 '<text x="34" y="158" font-size="12.5" fill-opacity="0.72">[space] mode   [−/+] power   [ [ / ] ] speed   [ , / . ] radius</text>'+
 '<text x="34" y="180" font-size="12.5" fill-opacity="0.72">[c] palette   [m] sound   [g] glow   [x] clear   [h] hide</text>';
svg.appendChild(hud);
var hHint=hud.querySelector('#hHint'),hMode=hud.querySelector('#hMode'),hMeta=hud.querySelector('#hMeta');
var HINTS=['move · push a swell      click · drop a ripple','move · steer the swell     click · drop a ripple','move · stir the field      click · ripple','move · stir the field      click · ripple','move · swirl the field     click · ripple','hover · magnify one tile    click · pin it','click · highlight a tile (toggle)    [x] clear'];
var hudHidden=false,hudTimer=null;
function hudWake(){if(hudHidden)return;hud.style.opacity='1';clearTimeout(hudTimer);hudTimer=setTimeout(function(){hud.style.opacity='0.14';},6000);}
function hudSync(){hHint.textContent=HINTS[mode];hMode.textContent='mode: '+MODES[mode]+'    power: '+gains[mode].toFixed(1)+'x';hMeta.textContent='speed: '+speed.toFixed(1)+'x    radius: '+Math.round(radiusScale*100)+'%    palette: '+PAL[palIdx].n+'    sound: '+(soundOn?'on':'off')+(N>1700?'    ['+N+'·lite]':'');}

/* ---- audio ---- */
var actx=null,soundOn=false,SC=[261.63,293.66,329.63,392,440,523.25,587.33,659.25];
function aInit(){if(actx)return;try{actx=new (window.AudioContext||window.webkitAudioContext)();}catch(e){}}
function tone(f){if(!actx||!soundOn)return;var t=actx.currentTime,o=actx.createOscillator(),g=actx.createGain();o.type='triangle';o.frequency.value=f;g.gain.setValueAtTime(0.0001,t);g.gain.linearRampToValueAtTime(0.14,t+0.012);g.gain.exponentialRampToValueAtTime(0.0001,t+1.1);o.connect(g);g.connect(actx.destination);o.start(t);o.stop(t+1.15);}

/* ---- pointer / ripples ---- */
function toVB(x,y){if(!ctmInv)updCTM();var p=svg.createSVGPoint();p.x=x;p.y=y;return p.matrixTransform(ctmInv);}
var mvx=-1e5,mvy=-1e5,realActive=false,lastMove=performance.now(),T=0,autoRip=0,windAng=0,hoveredIdx=-1,ripples=[];
function pos(e){var p=e.touches&&e.touches[0]?e.touches[0]:e;return [p.clientX,p.clientY];}
function onMove(e){var p=pos(e),v=toVB(p[0],p[1]);mvx=v.x;mvy=v.y;realActive=true;lastMove=performance.now();hoveredIdx=(e.target&&e.target._ti!==undefined)?e.target._ti:-1;setGlow(mvx,mvy,true);}
function onDown(e){var p=pos(e),v=toVB(p[0],p[1]);mvx=v.x;mvy=v.y;realActive=true;lastMove=performance.now();aInit();if(actx&&actx.state==='suspended')actx.resume();
 var idx=(e.target&&e.target._ti!==undefined)?e.target._ti:-1;
 if((mode===6||mode===5)&&idx>=0){picked[idx]=picked[idx]?0:1;if(soundOn)tone(SC[idx%SC.length]);}
 else{if(ripples.length<14)ripples.push({x:v.x,y:v.y,age:0});if(soundOn)tone(SC[Math.floor((1-p[1]/innerHeight)*SC.length)%SC.length]);}}
addEventListener('pointermove',onMove,{passive:true});addEventListener('pointerdown',onDown,{passive:true});
addEventListener('pointerleave',function(){realActive=false;hoveredIdx=-1;setGlow(-9999,-9999,false);});
addEventListener('resize',function(){measure();setHaloR();});
addEventListener('keydown',function(e){var k=e.key.toLowerCase();
 if(k===' '){mode=(mode+1)%MODES.length;if(mode>=5)glow.style.opacity='0';e.preventDefault();}
 else if(k==='+'||k==='='){gains[mode]=Math.min(5,gains[mode]+0.2);}
 else if(k==='-'||k==='_'){gains[mode]=Math.max(0.2,gains[mode]-0.2);}
 else if(k===']'){speed=Math.min(4,speed*1.15);}
 else if(k==='['){speed=Math.max(0.1,speed/1.15);}
 else if(k==='.'){radiusScale=Math.min(2.5,radiusScale+0.15);setHaloR();}
 else if(k===','){radiusScale=Math.max(0.3,radiusScale-0.15);setHaloR();}
 else if(k==='c'){palIdx=(palIdx+1)%PAL.length;for(var s=0;s<curRGB.length;s++)tgtRGB[s]=slotCol(PAL[palIdx],s).slice();recolor=true;}
 else if(k==='m'){soundOn=!soundOn;aInit();if(actx&&actx.state==='suspended')actx.resume();if(soundOn)tone(440);}
 else if(k==='g'){haloOn=!haloOn;if(!haloShow())glow.style.opacity='0';}
 else if(k==='x'){picked.fill(0);}
 else if(k==='h'){hudHidden=!hudHidden;hud.style.opacity=hudHidden?'0':'1';if(!hudHidden)hudWake();}
 else{hudWake();return;}
 hudSync();hudWake();});
hudSync();hudWake();

/* ---- apply (per class) ---- */
function applyB(i,s,dx,dy){var M=BM[i];tiles[i].setAttribute('transform','matrix('+(s*M[0])+' '+(s*M[1])+' '+(s*M[2])+' '+(s*M[3])+' '+(s*M[4]+dx+cx[i]*(1-s))+' '+(s*M[5]+dy+cy[i]*(1-s))+')');}
function applyA(i,s,dx,dy){tiles[i].style.transform='translate('+(Ginv.a*dx+Ginv.c*dy)+'px,'+(Ginv.b*dx+Ginv.d*dy)+'px) scale('+s+')';}
var applyT=CLASSB?applyB:applyA;
function resetT(i){if(CLASSB)tiles[i].setAttribute('transform',baseStr[i]);else tiles[i].style.transform='';tiles[i].style.filter='';}

/* ---- main loop ---- */
function frame(now){T++;
 if(now-lastMove>CFG.IDLE_MS&&mode<5){var t=T*0.012;mvx=VW*0.5+Math.sin(t)*VW*0.33;mvy=VH*0.5+Math.sin(t*1.31+1.1)*VH*0.33;realActive=true;setGlow(mvx,mvy,true);glow.style.opacity=haloShow()?'0.32':'0';if(now-autoRip>2600){autoRip=now;if(ripples.length<14)ripples.push({x:mvx,y:mvy,age:0});if(soundOn)tone(SC[(T>>4)%SC.length]);}}
 if(recolor){var done=true;for(var s=0;s<curRGB.length;s++)for(var c=0;c<3;c++){var d=tgtRGB[s][c]-curRGB[s][c];if(Math.abs(d)>0.6)done=false;curRGB[s][c]+=d*0.12;}for(var i2=0;i2<N;i2++)tiles[i2].setAttribute('fill',r2h(curRGB[slotOf[i2]]));if(done)recolor=false;}
 for(var ri=ripples.length-1;ri>=0;ri--){ripples[ri].age++;if(ripples[ri].age*CFG.RIP_SPEED>Math.hypot(VW,VH)+CFG.RIP_W*3)ripples.splice(ri,1);}

 var wave=(mode<2),g=gains[mode],time=T*0.02*speed,Reff=CFG.R*radiusScale,lensR=CFG.R*0.5*radiusScale;
 if(mode===1){var ta=realActive?Math.atan2(mvy-VH/2,mvx-VW/2):windAng+0.004,dd=((ta-windAng+Math.PI*3)%(2*Math.PI))-Math.PI;windAng+=dd*0.05;}
 var sdx=Math.cos(windAng),sdy=Math.sin(windAng),kS=2*Math.PI/(VW*0.5);
 var hIdx=(mode===5)?hoveredIdx:-1,hcx=hIdx>=0?cx[hIdx]:0,hcy=hIdx>=0?cy[hIdx]:0;

 for(var i=0;i<N;i++){
  if(wave&&STRIDE>1&&(i%STRIDE)!==(T%STRIDE))continue;
  var px=cx[i]+ox[i],py=cy[i]+oy[i],tdx=0,tdy=0,ax=0,ay=0,crest=0,pulse=0;
  for(var r=0;r<ripples.length;r++){var rp=ripples[r],ddx=px-rp.x,ddy=py-rp.y,rd=Math.hypot(ddx,ddy)+0.001,ring=rp.age*CFG.RIP_SPEED,bnd=Math.exp(-((rd-ring)*(rd-ring))/(2*CFG.RIP_W*CFG.RIP_W));if(bnd>0.02){if(bnd>pulse)pulse=bnd;if(wave){tdx+=ddx/rd*bnd*CFG.RIP_AMP;tdy+=ddy/rd*bnd*CFG.RIP_AMP;}else{ax+=ddx/rd*bnd*CFG.RIP_PUSH;ay+=ddy/rd*bnd*CFG.RIP_PUSH;}}}
  var tScale=1,tBright=0;

  if(mode===0){var hx=0,hy=0,hh=0;for(var w=0;w<W;w++){var ph=spPh[i*W+w]-spW[w]*time,co=Math.cos(ph);hx+=qW[w]*ampR[w]*dW[w][0]*co;hy+=qW[w]*ampR[w]*dW[w][1]*co;hh+=ampR[w]*Math.sin(ph);}
   tdx+=hx*CFG.WAVE_AMP*g;tdy+=hy*CFG.WAVE_AMP*g;crest=Math.max(0,hh/sumA);
   if(realActive){var wd=Math.hypot(cx[i]-mvx,cy[i]-mvy),wg=Math.exp(-wd*wd/(2*(Reff*0.5)*(Reff*0.5)));crest=Math.max(crest,wg);tdx+=(cx[i]-mvx)/(wd+1)*wg*CFG.WAVE_AMP*1.5;tdy+=(cy[i]-mvy)/(wd+1)*wg*CFG.WAVE_AMP*1.5;}
   ox[i]+=(tdx-ox[i])*CFG.WAVE_EASE;oy[i]+=(tdy-oy[i])*CFG.WAVE_EASE;tScale=1+CFG.CREST_S*crest+CFG.RIP_SCALE*pulse;tBright=CFG.CREST_B*crest+pulse;
  }else if(mode===1){var phs=kS*(sdx*cx[i]+sdy*cy[i])-time*1.1,c2=Math.cos(phs);tdx+=0.85*CFG.SWELL_AMP*g*sdx*c2;tdy+=0.85*CFG.SWELL_AMP*g*sdy*c2;crest=Math.max(0,Math.sin(phs));ox[i]+=(tdx-ox[i])*CFG.WAVE_EASE;oy[i]+=(tdy-oy[i])*CFG.WAVE_EASE;tScale=1+CFG.CREST_S*crest+CFG.RIP_SCALE*pulse;tBright=CFG.CREST_B*crest+pulse;
  }else if(mode<5){ax+=-CFG.SPRING*ox[i];ay+=-CFG.SPRING*oy[i];if(realActive){var dx=px-mvx,dy=py-mvy,dist=Math.hypot(dx,dy)+0.001;if(dist<Reff){var fo=1-dist/Reff,fo2=fo*fo;crest=fo2;if(mode===2){var f=CFG.PUSH*g*fo2/dist;ax+=dx*f;ay+=dy*f;}else if(mode===3){var f1=CFG.PUSH*g*fo2/dist;ax-=dx*f1;ay-=dy*f1;}else{var f2=CFG.SWIRL*g*fo2/dist;ax+=(-dy+dx*0.25)*f2;ay+=(dx+dy*0.25)*f2;}}}
   vx[i]=(vx[i]+ax)*CFG.FR;vy[i]=(vy[i]+ay)*CFG.FR;ox[i]+=vx[i];oy[i]+=vy[i];var om=Math.hypot(ox[i],oy[i]);if(om>CFG.MAXO){var kk=CFG.MAXO/om;ox[i]*=kk;oy[i]*=kk;vx[i]*=0.5;vy[i]*=0.5;}tScale=1+CFG.GROW*crest+CFG.RIP_SCALE*pulse;tBright=CFG.BRIGHT*crest+pulse;
  }else if(mode===5){ox[i]+=(0-ox[i])*0.2;oy[i]+=(0-oy[i])*0.2;var m=0;if(i===hIdx)m=CFG.LENS_MAG*g;else if(hIdx>=0){var dl=Math.hypot(cx[i]-hcx,cy[i]-hcy);if(dl<lensR){var fl=1-dl/lensR;m=CFG.LENS_MAG*g*fl*fl*0.55;}}if(picked[i])m=Math.max(m,CFG.LENS_MAG*g);tScale=1+m+CFG.RIP_SCALE*pulse;tBright=0.3*m+pulse;
  }else{ox[i]+=(0-ox[i])*0.2;oy[i]+=(0-oy[i])*0.2;if(picked[i]){var pb=0.85+0.15*Math.sin(T*0.08+i*0.7);tScale=1+CFG.PICK_MAG*g*pb;tBright=CFG.BRIGHT*0.9;}tScale+=CFG.RIP_SCALE*pulse;tBright+=pulse;}

  sc[i]+=(tScale-sc[i])*0.22;br[i]+=(tBright-br[i])*0.2;
  if(!wave&&Math.abs(ox[i])<0.02&&Math.abs(oy[i])<0.02&&Math.abs(sc[i]-1)<0.004&&br[i]<0.01){if(dirty[i]){resetT(i);dirty[i]=0;}continue;}
  dirty[i]=1;applyT(i,sc[i],ox[i],oy[i]);if(DOFILTER)tiles[i].style.filter=br[i]>0.01?('brightness('+(1+br[i])+')'):'';
 }
